INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2150, 'divide', '/dɪˈvaɪd/', 'verb', '{"zh-TW":["劃分；除以"],"en":["to separate into parts"]}', NULL, 'divide into/among', '[{"en":"The project is divided into three phases.","zh-TW":"該項目分為三個階段。"},{"en":"Profits were divided equally among partners.","zh-TW":"利潤在合夥人之間平均分配。"}]', '{"noun":"division","verb":"divide"}', NULL, 2, 2150, NULL),
(2151, 'dividend', '/ˈdɪvɪdend/', 'noun', '{"zh-TW":["股利；紅利"],"en":["a portion of company profits distributed to shareholders"]}', NULL, 'pay a dividend / dividend yield / dividend per share / cut dividends', '[{"en":"The board declared a quarterly dividend of $0.50 per share.","zh-TW":"董事會宣佈每股季度股利為0.50美元。"},{"en":"Investors favored stocks with consistent dividend payments.","zh-TW":"投資者偏好股利持續發放的股票。"}]', '{"adjective":"dividend-paying"}', NULL, 3, 2151, NULL),
(2152, 'dividend payout', '/ˈdɪvɪdend ˈpeɪaʊt/', 'noun', '{"zh-TW":["股息支付；股利發放"],"en":["the distribution of company profits to shareholders as dividends"]}', NULL, 'increase dividend payout / dividend payout ratio', '[{"en":"The company increased its dividend payout to reward shareholders.","zh-TW":"公司增加了股息支付以回饋股東。"},{"en":"A high dividend payout ratio may indicate limited reinvestment in growth.","zh-TW":"高股息支付比率可能表明對增長的再投資有限。"}]', NULL, NULL, 5, 2152, NULL),
(2153, 'dividend payout ratio', '/ˈdɪvɪdend ˈpeɪaʊt ˈreɪʃioʊ/', 'noun', '{"zh-TW":["股息支付比率"],"en":["the percentage of earnings paid to shareholders as dividends"]}', NULL, 'calculate dividend payout ratio / high dividend payout ratio', '[{"en":"The company maintained a dividend payout ratio of 60% of earnings.","zh-TW":"公司維持了60%盈利的股息支付比率。"},{"en":"A high dividend payout ratio signals limited reinvestment in business growth.","zh-TW":"高股息支付比率表明對業務增長的再投資有限。"}]', NULL, NULL, 5, 2153, NULL),
(2154, 'dividend policy', '/ˈdɪvɪdɛnd ˈpɒlɪsi/', 'noun', '{"zh-TW":["股利政策"],"en":["a company''s approach to distributing profits to shareholders"]}', NULL, 'announce a dividend policy / stable dividend policy', '[{"en":"The board revised the dividend policy to increase shareholder returns.","zh-TW":"董事會修訂了股利政策以增加股東回報。"},{"en":"A consistent dividend policy attracts income-focused investors.","zh-TW":"一致的股利政策吸引注重收益的投資者。"}]', NULL, NULL, 5, 2154, NULL),
(2155, 'dividend reinvestment', '/ˈdɪvɪdend ˌriːɪnˈvestmənt/', 'noun', '{"zh-TW":["股利再投資"],"en":["using dividends received to purchase more shares automatically"]}', NULL, 'dividend reinvestment plan / enroll in dividend reinvestment', '[{"en":"A dividend reinvestment plan compounds returns over time.","zh-TW":"股利再投資計劃隨時間複利增長回報。"},{"en":"She enrolled in the dividend reinvestment program to grow her holdings.","zh-TW":"她加入了股利再投資計劃以增加持股。"}]', '{"abbreviation":"DRIP"}', NULL, 5, 2155, NULL),
(2156, 'dividend reinvestment plan', '/ˈdɪvɪdend ˌriːɪnˈvestmənt plæn/', 'noun', '{"zh-TW":["股息再投資計劃"],"en":["a program allowing shareholders to reinvest dividends in additional shares"]}', NULL, 'enroll in a dividend reinvestment plan / dividend reinvestment plan benefits', '[{"en":"The dividend reinvestment plan allows investors to compound returns automatically.","zh-TW":"股息再投資計劃允許投資者自動複利回報。"},{"en":"Many long-term investors use a dividend reinvestment plan to grow their holdings.","zh-TW":"許多長期投資者使用股息再投資計劃來增加其持股。"}]', '{"abbreviation":"DRIP"}', NULL, 5, 2156, NULL),
(2157, 'dividend yield', '/ˈdɪvɪdend jiːld/', 'noun', '{"zh-TW":["股息殖利率"],"en":["the ratio of a company''s annual dividend to its share price"]}', NULL, 'calculate dividend yield / high dividend yield', '[{"en":"Investors seeking income focus on stocks with a high dividend yield.","zh-TW":"尋求收入的投資者專注於高股息殖利率的股票。"},{"en":"The dividend yield fell as the company''s share price rose rapidly.","zh-TW":"隨著公司股價快速上漲，股息殖利率下降了。"}]', NULL, NULL, 5, 2157, NULL),
(2158, 'division', 'dɪˈvɪʒən', 'noun', '{"zh-TW":["部門；分部","劃分"],"en":["a section of an organization","the act of dividing"]}', NULL, 'sales division/business division', '[{"en":"The Asia division reported record profits.","zh-TW":"亞洲部門報告了創紀錄的利潤。"}]', '{"verb":"divide","adjective":"divisional","adverb":"divisionally"}', NULL, 3, 2158, 338),
(2159, 'dock', '/''dɒk/', 'noun', '{"zh-TW":["碼頭；船塢"],"en":["a platform extending from the shore into the water, used for loading and unloading ships"]}', NULL, 'work at the dock / busy dock / loading dock', '[{"en":"Workers unloaded the cargo from the ship at the dock.","zh-TW":"工人在碼頭上從船上卸貨。"},{"en":"The dock was busy with container ships arriving and departing throughout the day.","zh-TW":"整個白天，碼頭都有貨櫃船在抵達和離開，非常繁忙。"}]', NULL, NULL, 1, 2159, NULL),
(2160, 'dock worker', '/''dɒk ˌwɜːrkər/', 'noun', '{"zh-TW":["碼頭工人；港口工人"],"en":["a laborer who loads and unloads ships at a dock"]}', NULL, 'hire dock workers / skilled dock worker / dock worker union', '[{"en":"Dock workers unloaded containers from the cargo ship throughout the night.","zh-TW":"碼頭工人整夜在貨船上卸貨集裝箱。"},{"en":"A dock worker strike halted operations at the port for three days.","zh-TW":"碼頭工人罷工使港口停運了三天。"}]', NULL, NULL, 4, 2160, NULL),
(2161, 'doctoral degree', '/ˈdɒktərəl dɪˈɡriː/', 'noun', '{"zh-TW":["博士學位"],"en":["the highest academic degree, usually requiring original research"]}', NULL, 'earn a doctoral degree / doctoral degree program', '[{"en":"Earning a doctoral degree requires years of research.","zh-TW":"獲得博士學位需要多年的研究。"},{"en":"She completed her doctoral degree in three years.","zh-TW":"她在三年內完成了博士學位。"}]', '{"abbreviation":"PhD","adjective":"doctoral"}', NULL, 5, 2161, NULL),
(2162, 'doctrinal', '/ˈdɒktrɪnəl/', 'adjective', '{"zh-TW":["教義的；學說的"],"en":["relating to a doctrine or set of beliefs"]}', NULL, 'doctrinal debate / doctrinal framework / doctrinal differences', '[{"en":"Doctrinal differences between scholars have shaped the field''s development.","zh-TW":"學者之間的學說差異塑造了該領域的發展。"},{"en":"The court''s doctrinal approach establishes binding legal principles.","zh-TW":"法院的教義方法確立了具有約束力的法律原則。"}]', '{"adverb":"doctrinally","noun":"doctrine"}', NULL, 3, 2162, NULL),
(2163, 'doctrine', '/ˈdɒktrɪn/', 'noun', '{"zh-TW":["教義；學說"],"en":["a set of beliefs or principles held by a group"]}', '{"root":{"text":"doct","meaning":"teach (教導)"},"suffix":{"text":"-rine","meaning":"thing (事物)"},"logic":"被教導的東西，即「教義」。"}', 'political doctrine / legal doctrine', '[{"en":"The party changed its economic doctrine.","zh-TW":"該黨改變了其經濟學說。"},{"en":"This is a fundamental doctrine of the religion.","zh-TW":"這是該宗教的基本教義。"}]', NULL, NULL, 3, 2163, NULL),
(2164, 'docudrama', '/ˈdɒkjʊdrɑːmə/', 'noun', '{"zh-TW":["紀錄劇；劇情紀錄片"],"en":["a film or television program dramatizing actual events"]}', NULL, 'produce a docudrama / historical docudrama / docudrama format', '[{"en":"The docudrama recreated key events from the company''s controversial history.","zh-TW":"這部紀錄劇重現了該公司富有爭議歷史中的關鍵事件。"},{"en":"Docudramas blend factual accuracy with dramatic storytelling.","zh-TW":"紀錄劇將事實準確性與戲劇化敘事融合在一起。"}]', NULL, NULL, 3, 2164, NULL),
(2165, 'document', '/ˈdɑːkjumənt/', 'noun / verb', '{"zh-TW":["文件；記錄"],"en":["a written or printed paper; to record"]}', NULL, 'official document', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要的文件。"},{"en":"Everything must be documented carefully.","zh-TW":"一切都必須仔細記錄。"}]', '{"noun":"document/documentation","verb":"document"}', NULL, 3, 2165, 107),
(2166, 'document management', '/ˈdɒkjʊmənt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["文件管理"],"en":["the systematic handling and storage of documents in an organization"]}', NULL, 'document management system / improve document management', '[{"en":"The new document management system reduced retrieval time by 60%.","zh-TW":"新的文件管理系統將文件檢索時間縮短了60%。"},{"en":"Secure document management is essential for compliance.","zh-TW":"安全的文件管理對合規至關重要。"}]', NULL, NULL, 5, 2166, NULL),
(2167, 'documentary', '/ˌdɒkjuˈmɛntəri/', 'noun', '{"zh-TW":["紀錄片"],"en":["a film based on real events"]}', NULL, 'nature documentary / documentary film', '[{"en":"I watched a documentary about climate change.","zh-TW":"我看了一部關於氣候變遷的紀錄片。"},{"en":"She directed an award-winning documentary.","zh-TW":"她執導了一部獲獎紀錄片。"}]', NULL, NULL, 4, 2167, NULL),
(2168, 'documentary credit', '/ˌdɒkjʊˈmentəri ˈkredɪt/', 'noun', '{"zh-TW":["跟單信用狀"],"en":["a letter of credit requiring specific documents before payment is made"]}', NULL, 'issue a documentary credit / documentary credit payment', '[{"en":"The bank issued a documentary credit to guarantee payment for the shipment.","zh-TW":"銀行開立了跟單信用狀以保證貨運付款。"},{"en":"Documentary credits reduce risk in international trade by requiring proof of delivery.","zh-TW":"跟單信用狀通過要求交貨證明降低了國際貿易的風險。"}]', NULL, NULL, 5, 2168, NULL),
(2169, 'documentation', 'ˌdɒkjʊmɛnˈteɪʃən', 'noun', '{"zh-TW":["文件；記錄","文檔"],"en":["written records","the act of documenting"]}', NULL, 'proper documentation/submit documentation', '[{"en":"Please submit complete documentation.","zh-TW":"請提交完整的文件。"}]', '{"verb":"document","adjective":"documented"}', NULL, 5, 2169, 551),
(2170, 'docuseries', '/ˈdɒkjʊˌsɪəriːz/', 'noun', '{"zh-TW":["紀錄片系列；紀實系列"],"en":["a documentary presented as a series of episodes"]}', NULL, 'produce a docuseries / streaming docuseries / true crime docuseries', '[{"en":"The docuseries about climate change aired over four consecutive weeks.","zh-TW":"關於氣候變化的紀錄片系列連續四週播出。"},{"en":"True crime docuseries have become enormously popular on streaming platforms.","zh-TW":"真實犯罪紀錄片系列在串流媒體平台上大受歡迎。"}]', NULL, NULL, 4, 2170, NULL),
(2171, 'dog', '/dɒɡ/', 'noun', '{"zh-TW":["狗"],"en":["a common domestic animal"]}', NULL, 'guide dog / dog-eat-dog', '[{"en":"It is a dog-eat-dog world in sales.","zh-TW":"銷售業是個競爭激烈的世界。"},{"en":"Some offices allow employees to bring dogs.","zh-TW":"有些辦公室允許員工帶狗。"}]', '{"noun":"dog"}', NULL, 1, 2171, NULL),
(2172, 'dogmatic', '/''dɒɡˌmætɪk/', 'adjective', '{"zh-TW":["武斷的；教條主義的"],"en":["inclined to lay down principles as incontrovertibly true; asserting beliefs with unwarranted certainty"]}', NULL, 'dogmatic attitude / dogmatic belief / dogmatic approach', '[{"en":"A dogmatic approach to management can stifle creativity and discourage new ideas.","zh-TW":"武斷的管理方式可能會扼殺創造力並阻礙新想法。"},{"en":"She rejected the dogmatic views of her predecessors and sought evidence-based solutions.","zh-TW":"她拒絕了前人的教條主義觀點，尋求以證據為基礎的解決方案。"}]', '{"adverb":"dogmatically","noun":"dogmatism","noun2":"dogma"}', NULL, 3, 2172, NULL),
(2173, 'dollar', '/ˈdɒlər/', 'noun', '{"zh-TW":["美元"],"en":["the basic unit of money in the US"]}', NULL, 'dollar sign / dollar amount', '[{"en":"The total comes to 500 dollars.","zh-TW":"總共是500美元。"},{"en":"The dollar weakened against the euro.","zh-TW":"美元對歐元貶值了。"}]', '{"noun":"dollar"}', NULL, 2, 2173, NULL),
(2174, 'domain', '/doʊˈmeɪn/', 'noun', '{"zh-TW":["網域；領域","領域；域"],"en":["an area of activity; a website address","an area of knowledge or activity","an internet address"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"logic":"主人管轄的範圍，即「領域」。"}', 'domain name / public domain; public domain / domain name / domain knowledge', '[{"en":"Register a domain name for your website.","zh-TW":"為你的網站註冊一個網域名稱。"},{"en":"That''s outside my domain of expertise.","zh-TW":"那不在我的專業領域內。"},{"en":"This issue falls outside my domain of expertise.","zh-TW":"這個問題不在我的專業領域範圍內。"},{"en":"She registered a new domain name for her website.","zh-TW":"她為網站註冊了一個新網域名稱。"}]', NULL, NULL, 2, 2174, NULL),
(2175, 'domestic', '/dəˈmestɪk/', 'adjective', '{"zh-TW":["國內的；家庭的"],"en":["relating to one''s own country; relating to home"]}', NULL, 'domestic market/flight', '[{"en":"Domestic sales increased by 15%.","zh-TW":"國內銷售額增長了15%。"},{"en":"The airline offers both domestic and international flights.","zh-TW":"該航空公司提供國內和國際航班。"}]', '{"adjective":"domestic","adverb":"domestically"}', NULL, 3, 2175, 339),
(2176, 'domestic market', '/dəˈmestɪk ˈmɑːrkɪt/', 'noun', '{"zh-TW":["國內市場"],"en":["the market for goods and services within a company''s home country"]}', NULL, 'target the domestic market / domestic market share', '[{"en":"The company focused on the domestic market before considering exports.","zh-TW":"公司在考慮出口之前專注於國內市場。"},{"en":"Strong domestic market performance offset weak international sales.","zh-TW":"強勁的國內市場表現抵消了疲弱的國際銷售。"}]', '{"opposite":"international market","synonym":"home market"}', NULL, 5, 2176, NULL),
(2177, 'dominance', '/ˈdɒmɪnəns/', 'noun', '{"zh-TW":["主導地位；優勢"],"en":["the power or right to control others; the state of being most powerful"]}', NULL, 'market dominance / political dominance / technological dominance', '[{"en":"The company''s market dominance allowed it to influence pricing across the sector.","zh-TW":"公司的市場主導地位使其能夠影響整個行業的定價。"},{"en":"Technological dominance in semiconductors is central to national security strategies.","zh-TW":"半導體技術主導地位是國家安全戰略的核心。"}]', '{"verb":"dominate","adjective":"dominant"}', NULL, 3, 2177, NULL),
(2178, 'dominate', '/ˈdɑːmɪneɪt/', 'verb', '{"zh-TW":["主導；支配","主宰；支配"],"en":["to have control or influence over","to have a commanding influence over"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使自己成為主人，即「支配」。"}', 'dominate the market; dominate the market / dominate the conversation', '[{"en":"The company dominates the smartphone market.","zh-TW":"該公司主導智慧型手機市場。"},{"en":"One topic dominated the meeting.","zh-TW":"一個話題主導了會議。"},{"en":"The company dominates the smartphone market.","zh-TW":"這家公司主宰了智慧型手機市場。"},{"en":"He tends to dominate conversations.","zh-TW":"他往往主導談話。"}]', '{"noun":"dominance","verb":"dominate","adjective":"dominant","noun2":"dominance"}', NULL, 3, 2178, NULL),
(2179, 'donate', '/ˈdoʊneɪt/', 'verb', '{"zh-TW":["捐贈；捐獻","捐贈"],"en":["to give money or goods to a cause","to give money or goods for a good cause"]}', '{"root":{"text":"don","meaning":"give (給予)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使給予，即「捐贈」。"}', 'donate money/blood; donate money / donate blood / donate to charity', '[{"en":"She donated $10,000 to charity.","zh-TW":"她捐了一萬美元給慈善機構。"},{"en":"Many employees donated blood.","zh-TW":"許多員工捐了血。"},{"en":"She donated $1000 to the charity.","zh-TW":"她捐了1000美元給慈善機構。"},{"en":"Would you like to donate blood?","zh-TW":"你願意捐血嗎？"}]', '{"noun":"donation/donor","verb":"donate","noun2":"donor"}', NULL, 2, 2179, NULL),
(2180, 'door', '/dɔːr/', 'noun', '{"zh-TW":["門"],"en":["a movable barrier at the entrance"]}', NULL, 'next door / open door policy', '[{"en":"Our office has an open door policy.","zh-TW":"我們辦公室有開放門戶政策。"},{"en":"Please close the door behind you.","zh-TW":"請隨手關門。"}]', '{"noun":"door","noun2":"doorway"}', NULL, 1, 2180, NULL),
(2181, 'door-to-door delivery', '/''dɔːr tə dɔːr dɪˌlɪvəri/', 'noun', '{"zh-TW":["門到門配送；到門服務"],"en":["a shipping service in which goods are transported directly from the sender''s location to the recipient''s address"]}', NULL, 'offer door-to-door delivery / door-to-door delivery service / choose door-to-door delivery', '[{"en":"The courier company offers door-to-door delivery within twenty-four hours for most cities.","zh-TW":"這家快遞公司在大多數城市提供二十四小時內的門到門配送服務。"},{"en":"Door-to-door delivery is particularly convenient for e-commerce businesses.","zh-TW":"門到門配送對電子商務業務特別方便。"}]', NULL, NULL, 5, 2181, NULL),
(2182, 'doorman', '/''dɔːrmæn/', 'noun', '{"zh-TW":["門衛；守門人"],"en":["a person employed to stand at the door of a hotel or building to assist visitors"]}', NULL, 'hotel doorman / greet by the doorman / tip the doorman', '[{"en":"The doorman greeted every guest with a warm smile and held the door open.","zh-TW":"門衛面帶微笑迎接每位客人，並為他們開門。"},{"en":"She asked the doorman to hail a taxi to the airport.","zh-TW":"她請門衛叫了一輛計程車去機場。"}]', NULL, NULL, 3, 2182, NULL),
(2183, 'doping', '/''dəʊpɪŋ/', 'noun', '{"zh-TW":["禁藥使用；違禁藥物"],"en":["the use of prohibited performance-enhancing drugs in sport"]}', NULL, 'anti-doping / doping test / doping scandal', '[{"en":"Strict anti-doping regulations are enforced at all Olympic events.","zh-TW":"嚴格的反禁藥規定在所有奧運賽事中執行。"},{"en":"The cyclist was stripped of his title after testing positive for doping.","zh-TW":"這位自行車手在禁藥測試呈陽性後被剝奪了冠軍頭銜。"}]', NULL, NULL, 2, 2183, NULL),
(2184, 'dormitory', '/ˈdɔːrmɪtɔːri/', 'noun', '{"zh-TW":["宿舍"],"en":["a building where students live at school"]}', NULL, 'dormitory room / student dormitory', '[{"en":"First-year students live in the dormitory.","zh-TW":"大一學生住在宿舍。"},{"en":"The dormitory has a shared kitchen.","zh-TW":"宿舍有共用廚房。"}]', NULL, NULL, 3, 2184, NULL),
(2185, 'dosage', '/ˈdəʊsɪdʒ/', 'noun', '{"zh-TW":["劑量；用量"],"en":["the amount of medicine to be taken at one time"]}', NULL, 'recommended dosage / correct dosage', '[{"en":"Follow the recommended dosage on the label.","zh-TW":"請遵照標籤上的建議劑量服用。"},{"en":"The dosage must be adjusted for elderly patients.","zh-TW":"老年病患的劑量必須調整。"}]', '{"noun":"dose","verb":"dose"}', NULL, 2, 2185, NULL),
(2186, 'dose', '/doʊs/', 'noun', '{"zh-TW":["劑量"],"en":["a quantity of medicine taken at one time"]}', '{"root":{"text":"dose","meaning":"giving (給予)"},"logic":"源自希臘語 dosis（給予的量）。"}', 'recommended dose / daily dose / overdose', '[{"en":"Take one dose every four hours.","zh-TW":"每四小時服用一劑。"},{"en":"The doctor increased the dose of medication.","zh-TW":"醫生增加了藥物劑量。"}]', '{"noun":"dosage","verb":"dose"}', NULL, 1, 2186, NULL),
(2187, 'dossier', '/ˈdɒsieɪ/', 'noun', '{"zh-TW":["檔案；案卷"],"en":["a collection of documents about a particular person or topic"]}', NULL, 'compile a dossier / confidential dossier / submit a dossier', '[{"en":"The team compiled a dossier on each potential acquisition target.","zh-TW":"團隊針對每個潛在收購目標編制了檔案。"},{"en":"A dossier of evidence was submitted to the regulatory authority.","zh-TW":"一份證據案卷被提交給監管機構。"}]', NULL, NULL, 3, 2187, NULL),
(2188, 'double', 'ˈdʌbəl', 'adjective', '{"zh-TW":["雙倍的；兩倍的","雙重的"],"en":["twice as much","having two parts"]}', NULL, 'double the budget/double-check', '[{"en":"Sales doubled compared to last year.","zh-TW":"銷售額與去年相比翻倍。"}]', '{"verb":"double","adverb":"doubly"}', NULL, 2, 2188, NULL),
(2189, 'double degree', '/''dʌbəl dɪˌɡriː/', 'noun', '{"zh-TW":["雙學位"],"en":["a program allowing a student to earn two different degrees simultaneously"]}', NULL, 'enroll in a double degree / complete a double degree / double degree program', '[{"en":"She enrolled in a double degree program studying both economics and international law.","zh-TW":"她攻讀了同時學習經濟學和國際法的雙學位計劃。"},{"en":"A double degree is demanding but significantly enhances career opportunities.","zh-TW":"雙學位要求很高，但顯著增強了職業機會。"}]', NULL, NULL, 5, 2189, NULL),
(2190, 'double occupancy', '/ˈdʌbəl ˌɒkjʊpənsi/', 'noun', '{"zh-TW":["雙人入住"],"en":["a hotel rate based on two people sharing a room"]}', NULL, 'double occupancy rate / book on double occupancy', '[{"en":"The hotel rate is based on double occupancy.","zh-TW":"飯店房價是基於雙人入住計算的。"},{"en":"Single travelers often pay extra when the rate assumes double occupancy.","zh-TW":"單人旅行者在房價假設雙人入住時通常需要支付額外費用。"}]', NULL, NULL, 5, 2190, NULL),
(2191, 'double taxation', '/ˈdʌbəl tækˈseɪʃən/', 'noun', '{"zh-TW":["雙重課稅"],"en":["when income is taxed twice, typically in two different jurisdictions"]}', NULL, 'avoid double taxation / double taxation agreement', '[{"en":"A tax treaty helps businesses avoid double taxation on overseas income.","zh-TW":"稅務協定幫助企業避免對海外收入雙重課稅。"},{"en":"Double taxation discourages cross-border investment.","zh-TW":"雙重課稅阻礙了跨境投資。"}]', NULL, NULL, 5, 2191, NULL),
(2192, 'double-entry', '/ˈdʌbəl ˈɛntri/', 'adjective', '{"zh-TW":["複式記帳的"],"en":["a bookkeeping system where each transaction is recorded twice"]}', NULL, 'double-entry bookkeeping / double-entry accounting', '[{"en":"Double-entry bookkeeping ensures all transactions balance.","zh-TW":"複式記帳確保所有交易保持平衡。"},{"en":"Accountants use double-entry bookkeeping to prevent errors.","zh-TW":"會計師使用複式記帳來防止錯誤。"}]', NULL, NULL, 4, 2192, NULL),
(2193, 'double-entry bookkeeping', '/ˈdʌbəl ˈentri ˈbʊkkiːpɪŋ/', 'noun', '{"zh-TW":["複式記帳法"],"en":["a system where every transaction is recorded as both a debit and a credit"]}', NULL, 'apply double-entry bookkeeping / double-entry bookkeeping system', '[{"en":"Double-entry bookkeeping ensures the accounting equation always balances.","zh-TW":"複式記帳法確保會計等式始終平衡。"},{"en":"The accounting software automatically applies double-entry bookkeeping.","zh-TW":"會計軟體自動應用複式記帳法。"}]', NULL, NULL, 5, 2193, NULL),
(2194, 'doubt', '/daʊt/', 'noun', '{"zh-TW":["懷疑；疑慮"],"en":["a feeling of uncertainty"]}', NULL, 'no doubt / beyond doubt', '[{"en":"There is no doubt about his ability.","zh-TW":"他的能力毫無疑問。"},{"en":"I doubt that will work.","zh-TW":"我懷疑那行不通。"}]', '{"noun":"doubt","verb":"doubt","adjective":"doubtful","adverb":"doubtfully"}', NULL, 2, 2194, NULL),
(2195, 'dough', '/''dəʊ/', 'noun', '{"zh-TW":["麵團；麵糰"],"en":["a thick, malleable mixture of flour and liquid, used for baking bread, pastries, and pasta"]}', NULL, 'knead the dough / let the dough rise / roll out the dough', '[{"en":"She kneaded the bread dough by hand for ten minutes before letting it rise.","zh-TW":"她用手揉捏麵團十分鐘，然後讓它發酵。"},{"en":"The pizza dough needs to rest for at least an hour before shaping.","zh-TW":"披薩麵團在塑形之前需要靜置至少一個小時。"}]', NULL, NULL, 2, 2195, NULL),
(2196, 'down payment', '/daʊn ˈpeɪmənt/', 'noun', '{"zh-TW":["頭期款；首付款"],"en":["an initial payment made when buying something on credit"]}', NULL, 'make a down payment / down payment requirement', '[{"en":"A 20% down payment is typically required for a mortgage.","zh-TW":"購買房屋通常需要20%的頭期款。"},{"en":"She saved for years to accumulate the down payment.","zh-TW":"她存了多年才積累到頭期款。"}]', NULL, NULL, 4, 2196, NULL),
(2197, 'downgrade', '/ˈdaʊnɡreɪd/', 'verb', '{"zh-TW":["降級；下調評級"],"en":["to reduce the grade, status, or rating of something"]}', NULL, 'downgrade a credit rating / stock downgraded', '[{"en":"The credit agency downgraded the company''s bond rating to junk.","zh-TW":"信用評級機構將公司的債券評級下調至垃圾級。"},{"en":"The analyst downgraded the stock from buy to hold.","zh-TW":"分析師將股票從買入下調至持有。"}]', '{"noun":"downgrade","adjective":"downgraded"}', NULL, 3, 2197, NULL),
(2198, 'download', '/ˈdaʊnloʊd/', 'verb', '{"zh-TW":["下載"],"en":["to copy data from the internet to a computer"]}', NULL, 'download a file / free download', '[{"en":"Download the app for free.","zh-TW":"免費下載這個應用程式。"},{"en":"The download is almost complete.","zh-TW":"下載快要完成了。"}]', '{"noun":"download"}', NULL, 3, 2198, NULL),
(2199, 'downsize', '/ˈdaʊnsaɪz/', 'verb', '{"zh-TW":["縮編；裁員"],"en":["to reduce the size or number of employees in an organization"]}', NULL, 'downsize the workforce / company downsizing', '[{"en":"The firm downsized its operations after the market contracted.","zh-TW":"市場萎縮後，公司縮減了其運營規模。"},{"en":"Thousands of employees were laid off during the downsizing.","zh-TW":"在縮編過程中，數千名員工被裁員。"}]', '{"noun":"downsizing","adjective":"downsized"}', NULL, 3, 2199, 674);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2200, 'downsizing', '/ˈdaʊnsaɪzɪŋ/', 'noun', '{"zh-TW":["裁員；縮減規模"],"en":["reducing the size of a workforce or organization"]}', NULL, 'corporate downsizing / downsizing plan', '[{"en":"Downsizing was necessary to cut operating costs.","zh-TW":"裁員是削減營運成本的必要措施。"},{"en":"The downsizing affected nearly every department.","zh-TW":"裁員幾乎影響到每個部門。"}]', '{"verb":"downsize","noun":"downsizer"}', NULL, 4, 2200, NULL),
(2201, 'downstream', '/ˈdaʊnstriːm/', 'adjective', '{"zh-TW":["下游的"],"en":["relating to the later stages of production or supply chain activities"]}', NULL, 'downstream distribution / downstream partner / downstream operations', '[{"en":"Downstream operations include packaging, distribution, and retail.","zh-TW":"下游運營包括包裝、分銷和零售。"},{"en":"Disruptions in downstream channels delay goods reaching end consumers.","zh-TW":"下游渠道的中斷延遲了商品到達最終消費者的時間。"}]', '{"opposite":"upstream"}', NULL, 4, 2201, 863),
(2202, 'downtime', '/ˈdaʊntaɪm/', 'noun', '{"zh-TW":["停機時間；系統停運"],"en":["a period when a system is not operational"]}', NULL, 'minimize downtime / planned downtime / unexpected downtime / downtime cost', '[{"en":"The system downtime lasted three hours due to a hardware failure.","zh-TW":"由於硬體故障，系統停機持續了三小時。"},{"en":"Unplanned downtime can cost millions in lost revenue.","zh-TW":"計劃外停機可能導致數百萬元的收入損失。"}]', '{"antonym":"uptime"}', NULL, 3, 2202, NULL),
(2203, 'downturn', '/ˈdaʊntɜːrn/', 'noun', '{"zh-TW":["低迷；下滑"],"en":["a decline in economic or business activity"]}', NULL, 'economic downturn / market downturn', '[{"en":"The economic downturn affected all sectors.","zh-TW":"經濟低迷影響了所有行業。"},{"en":"We survived the downturn by cutting costs.","zh-TW":"我們靠削減成本度過了低迷期。"}]', '{"noun":"downturn"}', NULL, 3, 2203, 778),
(2204, 'dozen', 'ˈdʌzən', 'noun', '{"zh-TW":["一打；十二個","很多"],"en":["a group of twelve","a large number"]}', NULL, 'a dozen/dozens of', '[{"en":"We ordered a dozen new computers.","zh-TW":"我們訂購了十二台新電腦。"}]', NULL, NULL, 2, 2204, NULL),
(2205, 'draft', '/dræft/', 'noun / verb', '{"zh-TW":["草稿；起草","草稿；草案"],"en":["a preliminary version; to write a first version","a preliminary version of a document"]}', '{"root":{"text":"draft","meaning":"draw (拉/畫)"},"logic":"源自 draw 的變體，指拉出的初步版本。"}', 'first/final draft; first draft / rough draft / draft proposal', '[{"en":"Please review the first draft of the proposal.","zh-TW":"請審閱提案的初稿。"},{"en":"He drafted the contract in one day.","zh-TW":"他一天內起草了合約。"},{"en":"I finished the first draft of my essay.","zh-TW":"我完成了論文的初稿。"},{"en":"The committee reviewed the draft proposal.","zh-TW":"委員會審查了提案草案。"}]', '{"noun":"draft","verb":"draft"}', NULL, 2, 2205, 340),
(2206, 'draft beer', '/drɑːft bɪər/', 'noun', '{"zh-TW":["生啤酒；桶裝啤酒"],"en":["beer served from a keg or barrel"]}', NULL, 'order draft beer / cold draft beer', '[{"en":"They have ten local draft beers on tap.","zh-TW":"他們有十種本地生啤酒可供選擇。"},{"en":"Draft beer is usually cheaper than bottled beer.","zh-TW":"生啤酒通常比瓶裝啤酒便宜。"}]', NULL, NULL, 4, 2206, NULL),
(2207, 'draft budget', '/drɑːft ˈbʌdʒɪt/', 'noun', '{"zh-TW":["預算草案"],"en":["an initial version of a budget submitted for review and approval"]}', NULL, 'prepare a draft budget / review the draft budget', '[{"en":"The draft budget was presented to the finance committee in November.","zh-TW":"預算草案在十一月提交給了財務委員會。"},{"en":"Several revisions were made before the draft budget was approved.","zh-TW":"預算草案在批准前進行了幾次修訂。"}]', NULL, NULL, 4, 2207, NULL),
(2208, 'draft contract', '/drɑːft ˈkɒntrækt/', 'noun', '{"zh-TW":["合約草案"],"en":["an initial version of a contract not yet signed or finalized"]}', NULL, 'review the draft contract / approve the draft contract', '[{"en":"The legal team reviewed the draft contract for any unfavorable clauses.","zh-TW":"法律團隊審查了合約草案中任何不利的條款。"},{"en":"Please sign and return the draft contract after review.","zh-TW":"請審閱後簽署並歸還合約草案。"}]', '{"verb":"draft","adjective":"drafted"}', NULL, 5, 2208, NULL),
(2209, 'drafting', '/ˈdrɑːftɪŋ/', 'noun', '{"zh-TW":["起草；草擬"],"en":["the process of writing an initial version of a document"]}', NULL, 'contract drafting / drafting a proposal / drafting process', '[{"en":"Contract drafting requires precision to avoid ambiguities.","zh-TW":"合約起草需要精確以避免歧義。"},{"en":"The drafting process for the terms of service took three weeks.","zh-TW":"服務條款的草擬過程耗時三週。"}]', '{"verb":"draft","noun":"draft"}', NULL, 3, 2209, NULL),
(2210, 'drain', '/dreɪn/', 'verb / noun', '{"zh-TW":["排水；耗盡"],"en":["to remove liquid; to use up resources","to remove liquid","to use up resources gradually"]}', '{"root":{"text":"drain","meaning":"dry (乾)"},"logic":"源自古英語 dreahnian（變乾），使水排去。"}', 'drain resources/energy; drain resources / brain drain / drain the water', '[{"en":"The project drained our budget.","zh-TW":"這個項目耗盡了我們的預算。"},{"en":"Brain drain is a serious issue for developing countries.","zh-TW":"人才外流對開發中國家是嚴重問題。"},{"en":"Please drain the water from the pool.","zh-TW":"請把游泳池的水排掉。"},{"en":"The long commute drains my energy.","zh-TW":"長途通勤耗盡我的精力。"}]', '{"noun":"drain/drainage","verb":"drain","noun2":"drainage"}', NULL, 2, 2210, NULL),
(2211, 'drama', '/ˈdrɑːmə/', 'noun', '{"zh-TW":["戲劇；戲劇性事件"],"en":["a play or performance for theater or TV"]}', NULL, 'drama series / drama queen', '[{"en":"She studied drama at university.","zh-TW":"她在大學學戲劇。"},{"en":"There''s always so much drama at work.","zh-TW":"工作中總是有那麼多戲劇性的事。"}]', '{"adjective":"dramatic","adverb":"dramatically"}', NULL, 2, 2211, NULL),
(2212, 'dramatic', '/drəˈmætɪk/', 'adjective', '{"zh-TW":["戲劇性的；顯著的","戲劇性的；巨大的"],"en":["sudden and striking; relating to drama","sudden and striking","relating to drama"]}', '{"root":{"text":"drama","meaning":"action/play (行動/戲)"},"suffix":{"text":"-tic","meaning":"relating to (相關的)"},"logic":"與戲劇性行動相關的。"}', 'dramatic increase/change; dramatic change / dramatic increase / dramatic effect', '[{"en":"There was a dramatic increase in profits.","zh-TW":"利潤有了顯著的增長。"},{"en":"The market saw dramatic changes.","zh-TW":"市場出現了劇烈的變化。"},{"en":"There has been a dramatic increase in sales.","zh-TW":"銷售額有了大幅增加。"},{"en":"The sunset was dramatic and beautiful.","zh-TW":"日落壯觀而美麗。"}]', '{"noun":"drama","adjective":"dramatic","adverb":"dramatically"}', NULL, 3, 2212, NULL),
(2213, 'draw', 'drɔː', 'verb', '{"zh-TW":["【主要意義-動詞】畫；拉；拔出","【次要意義-名詞】平局（比賽）","【次要意義-動詞】引起（注意/興趣）","【次要意義-動詞】（從帳戶）提取；得出（結論）"],"en":["[primary] to make a picture; to pull something","[secondary - noun] a tied result in a game or contest","[secondary - verb] to attract or pull in attention or interest","[secondary - verb] to withdraw money; to reach a conclusion"]}', NULL, 'draw a conclusion / draw attention to / draw on experience / draw up a contract', '[{"en":"The new product drew considerable attention at the trade fair.","zh-TW":"新產品在貿易展覽會上引起了相當大的關注。"},{"en":"The report draws on data collected over five years.","zh-TW":"報告借鑒了五年來收集的數據。"},{"en":"We can draw the conclusion that customer satisfaction has improved.","zh-TW":"我們可以得出結論，客戶滿意度已有所提高。"}]', '{"noun":"drawback, withdrawal"}', 'draw 有多個次要意義：draw attention（引起注意）、draw on（借鑒/依靠）、draw a conclusion（得出結論）、draw up a contract（起草合約），均為 TOEIC 高頻商業用語。', 1, 2213, NULL),
(2214, 'draw-down', '/ˈdrɔː daʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the act of accessing funds from an available credit facility or loan"]}', NULL, 'draw-down schedule / draw-down on the credit line', '[{"en":"The company made a draw-down of $2 million from its credit facility.","zh-TW":"公司從其信貸額度提取了200萬元。"},{"en":"Multiple draw-downs are allowed under the revolving credit agreement.","zh-TW":"循環信貸協議允許多次提款。"}]', '{"verb":"draw down"}', NULL, 3, 2214, NULL),
(2215, 'drawback', '/ˈdrɔːbæk/', 'noun', '{"zh-TW":["缺點；不利之處"],"en":["a disadvantage or negative aspect of something"]}', NULL, 'main drawback / overcome the drawback', '[{"en":"The main drawback of the system is its high implementation cost.","zh-TW":"該系統的主要缺點是其高昂的實施成本。"},{"en":"The proposal was accepted despite its drawbacks.","zh-TW":"儘管有缺點，提案還是被接受了。"}]', NULL, NULL, 3, 2215, NULL),
(2216, 'drawdown', '/ˈdrɔːdaʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the withdrawal of funds from a credit facility or investment account"]}', NULL, 'request a drawdown / drawdown schedule', '[{"en":"The company made a drawdown from its credit facility to fund operations.","zh-TW":"公司從信貸額度中提取資金以資助運營。"},{"en":"Each drawdown from the revolving credit was subject to lender approval.","zh-TW":"每次從循環信用中提取資金都需要貸款方批准。"}]', '{"verb":"draw down"}', NULL, 3, 2216, NULL),
(2217, 'drawdown facility', '/ˈdrɔːdaʊn fəˈsɪlɪti/', 'noun', '{"zh-TW":["提款設施；借款額度"],"en":["a credit arrangement allowing funds to be drawn as needed up to a limit"]}', NULL, 'access a drawdown facility / drawdown facility terms', '[{"en":"The project used a drawdown facility to manage construction phase spending.","zh-TW":"項目使用提款設施管理建設階段的支出。"},{"en":"A drawdown facility provides flexible access to funds without interest on unused portions.","zh-TW":"提款設施提供靈活的資金使用，未使用部分不計利息。"}]', NULL, NULL, 5, 2217, NULL),
(2218, 'drayage', '/''dreɪɪdʒ/', 'noun', '{"zh-TW":["短途運輸費；拖車費"],"en":["the transportation of freight over a short distance, especially from a port to a nearby warehouse"]}', NULL, 'arrange drayage / drayage cost / drayage service', '[{"en":"Drayage services transported containers from the port to the distribution center.","zh-TW":"拖車服務將貨櫃從港口運輸到配送中心。"},{"en":"Efficient drayage reduces the time cargo sits waiting at congested ports.","zh-TW":"高效的短途運輸減少了貨物在擁擠港口等待的時間。"}]', NULL, NULL, 3, 2218, NULL),
(2219, 'dream', '/driːm/', 'noun', '{"zh-TW":["夢想；夢"],"en":["a hope or ambition","images during sleep"]}', NULL, 'dream job / dream come true', '[{"en":"This is my dream job.","zh-TW":"這是我的夢想工作。"},{"en":"Starting my own business was a dream come true.","zh-TW":"創業是我夢想成真。"}]', '{"noun":"dream","verb":"dream","adjective":"dreamy","noun2":"dreamer"}', NULL, 2, 2219, NULL),
(2220, 'dressing', '/ˈdrɛsɪŋ/', 'noun', '{"zh-TW":["醬汁；調味醬"],"en":["a sauce or mixture used to flavor salads"]}', NULL, 'salad dressing / house dressing', '[{"en":"What dressing would you like on your salad?","zh-TW":"您的沙拉要什麼醬汁？"},{"en":"The house dressing is made with lemon and olive oil.","zh-TW":"本店醬汁是用檸檬和橄欖油製成的。"}]', NULL, NULL, 3, 2220, NULL),
(2221, 'dribble', '/''drɪbəl/', 'verb', '{"zh-TW":["帶球運球；運球"],"en":["in sports, to run while controlling a ball with small touches of the feet or hands"]}', NULL, 'dribble past / dribble skillfully / dribble down the court', '[{"en":"The basketball player dribbled past three defenders before shooting.","zh-TW":"這名籃球運動員運球越過三名防守球員後投籃。"},{"en":"She dribbled the soccer ball skillfully through the crowded midfield.","zh-TW":"她靈巧地運著足球穿越擁擠的中場。"}]', '{"noun":"dribble"}', NULL, 3, 2221, NULL),
(2222, 'drink', '/drɪŋk/', 'verb', '{"zh-TW":["喝；飲料"],"en":["to take liquid into the mouth","a liquid for drinking"]}', NULL, 'soft drink / drink water', '[{"en":"Would you like something to drink?","zh-TW":"你想喝點什麼嗎？"},{"en":"Soft drinks are available in the lounge.","zh-TW":"休息室有提供軟性飲料。"}]', '{"verb":"drink","noun":"drink","noun2":"drinker"}', NULL, 2, 2222, NULL),
(2223, 'drip campaign', '/drɪp kæmˈpeɪn/', 'noun', '{"zh-TW":["滴灌行銷活動；自動化郵件序列"],"en":["a series of automated emails sent over time to nurture leads"]}', NULL, 'run a drip campaign / drip campaign sequence / design a drip campaign', '[{"en":"The drip campaign guided prospects through the 30-day trial period.","zh-TW":"滴灌行銷活動引導潛在客戶完成30天試用期。"},{"en":"A well-designed drip campaign increases conversion rates.","zh-TW":"精心設計的滴灌行銷活動提高了轉換率。"}]', NULL, NULL, 5, 2223, NULL),
(2224, 'drive', '/draɪv/', 'verb', '{"zh-TW":["開車；驅動"],"en":["to operate a vehicle","to cause something to happen"]}', NULL, 'drive growth / drive to work', '[{"en":"Innovation drives our growth.","zh-TW":"創新驅動我們的成長。"},{"en":"She drives to work every day.","zh-TW":"她每天開車上班。"}]', '{"verb":"drive","noun":"driver","noun2":"drive"}', NULL, 2, 2224, NULL),
(2225, 'drop', '/drɑːp/', 'verb / noun', '{"zh-TW":["下降；放棄"],"en":["to fall or decrease; to stop doing"]}', NULL, 'drop in price/sales', '[{"en":"Sales dropped by 5% last month.","zh-TW":"上個月銷售額下降了5%。"},{"en":"They decided to drop the project.","zh-TW":"他們決定放棄這個項目。"}]', '{"noun":"drop","verb":"drop"}', NULL, 1, 2225, NULL),
(2226, 'drop shipment', '/drɒp ˈʃɪpmənt/', 'noun', '{"zh-TW":["直接發貨；代客發貨"],"en":["shipping goods directly from manufacturer to customer without going through the retailer"]}', NULL, 'use drop shipment / drop shipment model', '[{"en":"The online store uses a drop shipment model to avoid holding stock.","zh-TW":"網路商店使用代客發貨模式以避免持有庫存。"},{"en":"Drop shipment reduces warehousing costs for the retailer.","zh-TW":"代客發貨降低了零售商的倉儲成本。"}]', '{"verb":"drop ship"}', NULL, 5, 2226, NULL),
(2227, 'drought', '/draʊt/', 'noun', '{"zh-TW":["乾旱"],"en":["a prolonged period of abnormally low rainfall"]}', '{"root":{"text":"drought","meaning":"dryness (乾燥)"},"logic":"源自古英語 drugaþ（乾燥），指長期缺水。"}', 'severe drought / drought-resistant', '[{"en":"The drought destroyed most of the crops.","zh-TW":"乾旱摧毀了大部分的農作物。"},{"en":"The region is experiencing its worst drought in decades.","zh-TW":"該地區正經歷數十年來最嚴重的乾旱。"}]', NULL, NULL, 3, 2227, NULL),
(2228, 'dry', '/draɪ/', 'adjective', '{"zh-TW":["乾的；乾燥的"],"en":["not wet; without water"]}', NULL, 'dry season / dry cleaning', '[{"en":"The dry season affects our water supply.","zh-TW":"旱季影響我們的供水。"},{"en":"This suit needs dry cleaning.","zh-TW":"這套西裝需要乾洗。"}]', '{"adjective":"dry","verb":"dry","noun":"dryer","noun2":"drought"}', NULL, 1, 2228, NULL),
(2229, 'dry cleaning', '/draɪ ˈkliːnɪŋ/', 'noun', '{"zh-TW":["乾洗"],"en":["a cleaning process using solvents instead of water"]}', NULL, 'dry cleaning service / send to dry cleaning', '[{"en":"The hotel offers a same-day dry cleaning service.","zh-TW":"飯店提供當天乾洗服務。"},{"en":"Please leave your items at the front desk for dry cleaning.","zh-TW":"請將衣物留在前台進行乾洗。"}]', NULL, NULL, 4, 2229, NULL),
(2230, 'dry run', '/draɪ rʌn/', 'noun', '{"zh-TW":["試演；演習；預演"],"en":["a rehearsal or simulation of a process to identify problems before the real event"]}', NULL, 'conduct a dry run / dry run of the launch', '[{"en":"The team conducted a dry run of the system migration over the weekend.","zh-TW":"團隊在週末進行了系統遷移的演習。"},{"en":"A dry run of the product launch revealed several communication gaps.","zh-TW":"產品發布的預演揭示了幾個溝通空白。"}]', NULL, NULL, 3, 2230, NULL),
(2231, 'due', '/djuː/', 'adjective', '{"zh-TW":["到期的；應付的"],"en":["expected at a certain time; owed"]}', NULL, 'due date/due to', '[{"en":"The payment is due on the 15th.","zh-TW":"付款到期日是15號。"},{"en":"The delay was due to bad weather.","zh-TW":"延誤是由於惡劣天氣。"}]', '{"adjective":"due"}', NULL, 1, 2231, 341),
(2232, 'due date', '/djuː deɪt/', 'noun', '{"zh-TW":["到期日；截止日"],"en":["the date by which a payment or task must be completed"]}', NULL, 'payment due date / invoice due date / extend the due date', '[{"en":"The invoice has a due date of 30 days from the date of issue.","zh-TW":"發票的到期日為開票日起30天。"},{"en":"Missing the due date may result in late payment penalties.","zh-TW":"錯過到期日可能導致逾期付款罰款。"}]', NULL, NULL, 3, 2232, NULL),
(2233, 'due diligence', '/djuː ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["盡職調查"],"en":["a thorough investigation before a business transaction"]}', NULL, 'conduct due diligence / due diligence process / due diligence report', '[{"en":"Buyers must conduct due diligence before finalizing the deal.","zh-TW":"買家在完成交易前必須進行盡職調查。"},{"en":"The due diligence process uncovered hidden liabilities.","zh-TW":"盡職調查過程發現了隱藏的負債。"}]', '{"adjective":"due-diligent"}', NULL, 5, 2233, NULL),
(2234, 'due diligence checklist', '/djuː ˈdɪlɪdʒəns ˈtʃeklɪst/', 'noun', '{"zh-TW":["盡職調查清單"],"en":["a structured list of items to investigate during a due diligence process"]}', NULL, 'use a due diligence checklist / complete the due diligence checklist', '[{"en":"The due diligence checklist covered legal, financial, and operational areas.","zh-TW":"盡職調查清單涵蓋了法律、財務和運營領域。"},{"en":"A comprehensive checklist ensures no critical area is overlooked.","zh-TW":"全面的清單確保沒有關鍵領域被忽視。"}]', NULL, NULL, 5, 2234, NULL),
(2235, 'due diligence report', '/djuː ˈdɪlɪdʒəns rɪˈpɔːrt/', 'noun', '{"zh-TW":["盡職調查報告"],"en":["a detailed report summarizing the findings of a due diligence investigation"]}', NULL, 'prepare a due diligence report / review the due diligence report', '[{"en":"The due diligence report identified three significant risk areas.","zh-TW":"盡職調查報告識別了三個重要風險領域。"},{"en":"Investors rely on the due diligence report to inform acquisition decisions.","zh-TW":"投資者依賴盡職調查報告做出收購決策。"}]', NULL, NULL, 5, 2235, NULL),
(2236, 'due process', '/djuː ˈprɒses/', 'noun', '{"zh-TW":["正當程序"],"en":["fair legal treatment in accordance with established rules and principles"]}', NULL, 'follow due process / right to due process / ensure due process', '[{"en":"All employees have the right to due process in disciplinary matters.","zh-TW":"所有員工在紀律事項中均享有正當程序的權利。"},{"en":"The court ruled that due process had not been followed.","zh-TW":"法院裁定未遵循正當程序。"}]', NULL, NULL, 4, 2236, NULL),
(2237, 'duly', '/ˈdjuːli/', 'adverb', '{"zh-TW":["正式地；如期地"],"en":["in accordance with what is required; at the proper time"]}', NULL, 'duly signed / duly authorized / duly noted', '[{"en":"The contract was duly signed by both parties.","zh-TW":"合約由雙方正式簽署。"},{"en":"All submissions must be duly completed before the deadline.","zh-TW":"所有提交文件必須在截止日期前正式完成。"}]', '{"adjective":"due"}', NULL, 1, 2237, NULL),
(2238, 'duopoly', '/djuːˈɒpəli/', 'noun', '{"zh-TW":["雙頭壟斷"],"en":["a market situation in which only two companies dominate"]}', NULL, 'market duopoly / commercial duopoly / effective duopoly', '[{"en":"The smartphone market is often described as a duopoly dominated by Apple and Samsung.","zh-TW":"智能手機市場通常被描述為由蘋果和三星主導的雙頭壟斷。"},{"en":"A duopoly can reduce consumer choice as effectively as a monopoly.","zh-TW":"雙頭壟斷可以像壟斷一樣有效地減少消費者選擇。"}]', NULL, NULL, 3, 2238, NULL),
(2239, 'duplicate', '/ˈdjuːplɪkeɪt/', 'verb / noun', '{"zh-TW":["複製；副本"],"en":["to make an exact copy"]}', NULL, 'avoid duplication', '[{"en":"Please duplicate this report for all managers.","zh-TW":"請為所有經理複製這份報告。"},{"en":"We need to eliminate duplicate records.","zh-TW":"我們需要消除重複的記錄。"}]', '{"noun":"duplicate/duplication","verb":"duplicate"}', NULL, 3, 2239, 675),
(2240, 'durable goods', '/ˈdjʊərəbəl ɡʊdz/', 'noun', '{"zh-TW":["耐久財；耐用品"],"en":["products expected to last three or more years, such as appliances and vehicles"]}', NULL, 'orders for durable goods / durable goods market / decline in durable goods', '[{"en":"Orders for durable goods declined as consumer confidence fell.","zh-TW":"隨著消費者信心下降，耐久財訂單也有所減少。"},{"en":"Investment in durable goods is one measure of economic health and business confidence.","zh-TW":"耐久財投資是衡量經濟健康和商業信心的指標之一。"}]', NULL, NULL, 5, 2240, NULL),
(2241, 'duration', '/djuˈreɪʃən/', 'noun', '{"zh-TW":["持續時間"],"en":["the time during which something continues","the length of time something continues"]}', '{"root":{"text":"dur","meaning":"last/hard (持久)"},"suffix":{"text":"-ation","meaning":"state (狀態)"},"logic":"持續的狀態，即「持續時間」。"}', 'for the duration of; for the duration of / short duration', '[{"en":"The contract is valid for the duration of the project.","zh-TW":"合約在項目期間有效。"},{"en":"What is the duration of the training?","zh-TW":"培訓的持續時間是多長？"},{"en":"The flight duration is approximately 12 hours.","zh-TW":"飛行時間約12小時。"},{"en":"For the duration of the event, parking is free.","zh-TW":"活動期間停車免費。"}]', '{"noun":"duration","adjective":"durable","verb":"endure"}', NULL, 3, 2241, 108),
(2242, 'duty', '/ˈdjuːti/', 'noun', '{"zh-TW":["職責；關稅"],"en":["a moral or legal obligation; a tax on imports"]}', NULL, 'on/off duty', '[{"en":"It is your duty to report any safety issues.","zh-TW":"報告任何安全問題是你的職責。"},{"en":"Import duties have been raised.","zh-TW":"進口關稅已提高。"}]', '{"noun":"duty","adjective":"dutiful"}', NULL, 1, 2242, NULL),
(2243, 'duty of care', '/ˈdjuːti əv keər/', 'noun', '{"zh-TW":["注意義務；謹慎義務"],"en":["a legal obligation to take reasonable care to avoid causing harm to others"]}', NULL, 'fulfill duty of care / breach of duty of care', '[{"en":"Employers have a duty of care to maintain a safe working environment.","zh-TW":"雇主有注意義務維持安全的工作環境。"},{"en":"A breach of duty of care can result in legal liability.","zh-TW":"違反注意義務可能導致法律責任。"}]', NULL, NULL, 4, 2243, NULL),
(2244, 'duty roster', '/''djuːti ˌrɒstər/', 'noun', '{"zh-TW":["值班表；輪班表"],"en":["a list showing when each person in a group is to perform a particular duty"]}', NULL, 'check the duty roster / update the duty roster / post the duty roster', '[{"en":"The duty roster was posted each Monday for the following week.","zh-TW":"值班表每週一公布，適用於下一週。"},{"en":"She checked the duty roster to see when she was scheduled to work the weekend shift.","zh-TW":"她查看了值班表，確認她被安排在週末班工作。"}]', NULL, NULL, 4, 2244, NULL),
(2245, 'duty-free', '/ˈdjuːtiˌfriː/', 'adjective', '{"zh-TW":["免稅的"],"en":["not taxed, especially goods sold at airports"]}', NULL, 'duty-free shop / duty-free allowance', '[{"en":"Passengers can buy duty-free goods before boarding.","zh-TW":"乘客可以在登機前購買免稅商品。"},{"en":"The duty-free allowance is one liter of alcohol.","zh-TW":"免稅限額是一升酒精。"}]', NULL, NULL, 3, 2245, NULL),
(2246, 'duty-free shop', '/''djuːti friː ʃɒp/', 'noun', '{"zh-TW":["免稅店"],"en":["a store in an airport or on a ship where goods can be bought without paying customs duties"]}', NULL, 'browse the duty-free shop / duty-free shop allowance / luxury goods at duty-free', '[{"en":"She bought perfume and chocolates at the duty-free shop before boarding.","zh-TW":"她在登機前在免稅店買了香水和巧克力。"},{"en":"Duty-free shops offer international brands at reduced prices for travelers.","zh-TW":"免稅店為旅行者提供以優惠價格購買國際品牌商品的機會。"}]', NULL, NULL, 5, 2246, NULL),
(2247, 'dwell', '/dwel/', 'verb', '{"zh-TW":["居住；老是想著"],"en":["to live in a place","to think about something at length"]}', '{"root":{"text":"dwell","meaning":"lead astray/delay (耽擱)"},"logic":"源自古英語 dwellan（耽擱），引申為停留、居住。"}', 'dwell on / dwell in / dwelling place', '[{"en":"Don''t dwell on past mistakes.","zh-TW":"不要老想著過去的錯誤。"},{"en":"Many species dwell in the rainforest.","zh-TW":"許多物種棲息在雨林中。"}]', '{"noun":"dwelling","noun2":"dweller"}', NULL, 2, 2247, NULL),
(2248, 'dynamic', '/daɪˈnæmɪk/', 'adjective', '{"zh-TW":["動態的；有活力的","動態的；充滿活力的"],"en":["characterized by constant change and activity","characterized by constant change or activity"]}', '{"root":{"text":"dynam","meaning":"power (力量)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與力量和活動相關的，即「動態的」。"}', 'dynamic environment/market; dynamic environment / dynamic personality', '[{"en":"The tech industry is highly dynamic.","zh-TW":"科技產業高度動態。"},{"en":"She is a dynamic leader.","zh-TW":"她是一位有活力的領導者。"},{"en":"The business operates in a dynamic market.","zh-TW":"這家企業在活躍的市場中運營。"},{"en":"She has a very dynamic personality.","zh-TW":"她有非常有活力的個性。"}]', '{"noun":"dynamics","adjective":"dynamic","adverb":"dynamically"}', NULL, 3, 2248, 865),
(2249, 'dynamic pricing', '/daɪˈnæmɪk ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["動態定價"],"en":["adjusting prices in real-time based on supply, demand, or other factors"]}', NULL, 'implement dynamic pricing / dynamic pricing model / dynamic pricing algorithm', '[{"en":"Airlines use dynamic pricing to maximize revenue per seat.","zh-TW":"航空公司使用動態定價來最大化每個座位的收入。"},{"en":"Dynamic pricing can frustrate customers if changes are too frequent.","zh-TW":"如果變化過於頻繁，動態定價可能會讓客戶感到沮喪。"}]', NULL, NULL, 5, 2249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2250, 'e-commerce', '/ˈiːkɒmɜːrs/', 'noun', '{"zh-TW":["電子商務"],"en":["buying and selling goods and services over the internet"]}', NULL, 'e-commerce platform / B2C e-commerce / e-commerce growth', '[{"en":"E-commerce sales surged during the pandemic.","zh-TW":"疫情期間電子商務銷售額激增。"},{"en":"The brand expanded into e-commerce to reach new customers.","zh-TW":"品牌拓展至電子商務以觸及新客戶。"}]', '{"adjective":"e-commerce"}', NULL, 4, 2250, NULL),
(2251, 'e-commerce platform', '/ˈiːkɒmɜːrs ˈplætfɔːrm/', 'noun', '{"zh-TW":["電子商務平台"],"en":["a digital marketplace facilitating online buying and selling"]}', NULL, 'launch an e-commerce platform / e-commerce platform features', '[{"en":"The retailer launched an e-commerce platform to reach global customers.","zh-TW":"零售商推出了電子商務平台以觸及全球客戶。"},{"en":"An integrated e-commerce platform simplifies order and inventory management.","zh-TW":"整合的電子商務平台簡化了訂單和庫存管理。"}]', NULL, NULL, 5, 2251, NULL),
(2252, 'e-learning', '/ˈiː ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["電子學習；線上學習"],"en":["learning conducted via electronic means, especially online"]}', NULL, 'e-learning platform / e-learning course', '[{"en":"E-learning allows students to study from anywhere.","zh-TW":"電子學習允許學生在任何地方學習。"},{"en":"The company launched an e-learning program for employee development.","zh-TW":"公司推出了員工發展的電子學習計劃。"}]', NULL, NULL, 4, 2252, NULL),
(2253, 'e-learning platform', '/''iː ˌlɜːrnɪŋ ˌplætfɔːrm/', 'noun', '{"zh-TW":["電子學習平台；線上學習平台"],"en":["a digital system that provides educational content and learning tools online"]}', NULL, 'use an e-learning platform / e-learning platform features / popular e-learning platform', '[{"en":"She used an e-learning platform to complete a professional certification from home.","zh-TW":"她使用電子學習平台在家完成了一項專業認證。"},{"en":"E-learning platforms allow learners to study at their own pace and schedule.","zh-TW":"電子學習平台讓學習者可以按自己的節奏和時間表學習。"}]', NULL, NULL, 5, 2253, NULL),
(2254, 'e-waste', '/ˈiː weɪst/', 'noun', '{"zh-TW":["電子廢棄物；電廢"],"en":["discarded electronic devices such as computers and phones"]}', NULL, 'recycle e-waste / e-waste disposal / e-waste management', '[{"en":"Proper e-waste recycling recovers valuable metals and prevents pollution.","zh-TW":"妥善的電子廢棄物回收可回收貴重金屬並防止污染。"},{"en":"Developing countries often receive e-waste from wealthier nations.","zh-TW":"發展中國家通常接收來自富裕國家的電子廢棄物。"}]', NULL, NULL, 3, 2254, NULL),
(2255, 'eager', '/ˈiːɡər/', 'adjective', '{"zh-TW":["渴望的；熱切的"],"en":["strongly wanting to do or have something"]}', '{"root":{"text":"eager","meaning":"sharp/keen (尖銳/敏銳)"},"logic":"源自拉丁語 acer（尖銳的），指熱切渴望的。"}', 'eager to learn / eager for', '[{"en":"Students were eager to start the project.","zh-TW":"學生們渴望開始這個專案。"},{"en":"She is eager for new experiences.","zh-TW":"她熱切期望新體驗。"}]', '{"noun":"eagerness","adverb":"eagerly"}', NULL, 2, 2255, NULL),
(2256, 'early', '/ˈɜːrli/', 'adjective', '{"zh-TW":["早的；提前的"],"en":["before the expected time","near the beginning of a period"]}', NULL, 'early morning / early stage', '[{"en":"We are still in the early stages.","zh-TW":"我們仍處於早期階段。"},{"en":"She arrived early for the interview.","zh-TW":"她面試提前到達。"}]', '{"adjective":"early","adverb":"early"}', NULL, 2, 2256, NULL),
(2257, 'early adopter', '/ˈɜːrli əˈdɒptər/', 'noun', '{"zh-TW":["早期採用者"],"en":["a customer who uses a new product or technology before most other consumers"]}', NULL, 'target early adopters / early adopter feedback', '[{"en":"Early adopters provided valuable feedback that shaped product development.","zh-TW":"早期採用者提供了寶貴的反饋，塑造了產品發展方向。"},{"en":"Companies reward early adopters with discounts and exclusive features.","zh-TW":"公司以折扣和獨家功能獎勵早期採用者。"}]', NULL, NULL, 5, 2257, NULL),
(2258, 'early check-in', '/ˈɜːrli ˈtʃɛkɪn/', 'noun', '{"zh-TW":["提前入住"],"en":["checking in before the standard check-in time"]}', NULL, 'request early check-in / early check-in fee', '[{"en":"She requested early check-in due to an early morning flight.","zh-TW":"她因早班機而要求提前入住。"},{"en":"Early check-in is subject to availability and may incur a fee.","zh-TW":"提前入住視空房情況而定，可能需要支付費用。"}]', NULL, NULL, 5, 2258, NULL),
(2259, 'earn', '/ɜːrn/', 'verb', '{"zh-TW":["賺取；贏得"],"en":["to receive money for work; to gain through effort"]}', NULL, 'earn a living/reputation', '[{"en":"She earns a good salary as a consultant.","zh-TW":"她作為顧問賺取了不錯的薪水。"},{"en":"He earned the respect of his colleagues.","zh-TW":"他贏得了同事的尊重。"}]', '{"noun":"earnings","verb":"earn"}', NULL, 1, 2259, NULL),
(2260, 'earn-out', '/ˈɜːrn aʊt/', 'noun', '{"zh-TW":["業績對賭安排；收益補充"],"en":["a payment structure where the seller earns additional amounts based on future performance"]}', NULL, 'earn-out provision / negotiate an earn-out', '[{"en":"The acquisition included an earn-out provision based on three-year profit targets.","zh-TW":"收購包含基於三年利潤目標的業績對賭安排。"},{"en":"An earn-out aligns seller and buyer incentives during the transition.","zh-TW":"業績對賭安排在過渡期間使賣方和買方的激勵保持一致。"}]', NULL, NULL, 3, 2260, NULL),
(2261, 'earnings before interest and tax', '/ˈɜːrnɪŋz bɪˌfɔːr ˈɪntrəst ænd tæks/', 'noun', '{"zh-TW":["息稅前利潤"],"en":["operating profit before deducting interest expense and income taxes"]}', NULL, 'calculate EBIT / improve EBIT margin', '[{"en":"A higher EBIT indicates stronger operational efficiency.","zh-TW":"較高的息稅前利潤表明更強的運營效率。"},{"en":"EBIT is used to compare profitability across companies with different capital structures.","zh-TW":"息稅前利潤用於比較具有不同資本結構的公司的盈利能力。"}]', '{"abbreviation":"EBIT"}', NULL, 5, 2261, NULL),
(2262, 'earnings before interest and taxes', '/ˈɜːrnɪŋz bɪˈfɔːr ˈɪntrɪst ənd tæksɪz/', 'noun', '{"zh-TW":["息稅前利潤"],"en":["a measure of a company''s profitability excluding interest and tax costs"]}', NULL, 'calculate earnings before interest and taxes / earnings before interest and taxes margin / use earnings before interest and taxes', '[{"en":"Earnings before interest and taxes is commonly used to compare profitability across companies.","zh-TW":"息稅前利潤常用於比較不同公司之間的盈利能力。"},{"en":"A rising earnings before interest and taxes margin indicates improving operational efficiency.","zh-TW":"息稅前利潤率上升表明業務效率的提升。"}]', NULL, NULL, 5, 2262, NULL),
(2263, 'earnings before interest tax depreciation amortization', '/ˈɜːrnɪŋz bɪˈfɔːr ˈɪntrɪst tæks dɪˌpriːʃiˈeɪʃən əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["息稅折舊攤銷前利潤"],"en":["a measure of core operating performance excluding non-cash charges"]}', NULL, 'calculate EBITDA / EBITDA margin', '[{"en":"EBITDA is widely used to compare operational performance across companies.","zh-TW":"EBITDA被廣泛用於比較各公司的運營績效。"},{"en":"The company''s EBITDA margin improved to 25% following cost restructuring.","zh-TW":"在成本重組後，公司的EBITDA利潤率提升至25%。"}]', '{"abbreviation":"EBITDA"}', NULL, 5, 2263, NULL),
(2264, 'earnings call', '/ˈɜːrnɪŋz kɔːl/', 'noun', '{"zh-TW":["業績發布電話會議"],"en":["a conference call where a company discusses its financial results with analysts"]}', NULL, 'host an earnings call / earnings call transcript', '[{"en":"Management highlighted strong revenue growth during the earnings call.","zh-TW":"管理層在業績發布電話會議上強調了強勁的收入增長。"},{"en":"Analysts submitted questions about margins during the quarterly earnings call.","zh-TW":"分析師在季度業績發布電話會議上提交了有關利潤率的問題。"}]', NULL, NULL, 5, 2264, NULL),
(2265, 'earnings per share', '/ˈɜːrnɪŋz pər ʃɛr/', 'noun', '{"zh-TW":["每股盈餘"],"en":["a company''s profit divided by the number of outstanding shares"]}', NULL, 'earnings per share growth / diluted earnings per share', '[{"en":"Earnings per share rose to $3.50 this fiscal year.","zh-TW":"本財政年度每股盈餘增至3.50美元。"},{"en":"Analysts expected earnings per share to beat estimates.","zh-TW":"分析師預期每股盈餘將超過預期。"}]', '{"abbreviation":"EPS"}', NULL, 5, 2265, NULL),
(2266, 'earnings release', '/ˈɜːrnɪŋz rɪˈliːs/', 'noun', '{"zh-TW":["業績公告"],"en":["a public announcement of a company''s financial results for a reporting period"]}', NULL, 'issue an earnings release / earnings release date', '[{"en":"The earnings release showed a 15% increase in quarterly net income.","zh-TW":"業績公告顯示季度淨利潤增加了15%。"},{"en":"Investors study the earnings release for signs of operational improvement.","zh-TW":"投資者研究業績公告以尋找運營改善的跡象。"}]', NULL, NULL, 5, 2266, NULL),
(2267, 'earnings yield', '/ˈɜːrnɪŋz jiːld/', 'noun', '{"zh-TW":["盈利收益率"],"en":["the ratio of earnings per share to the market price per share"]}', NULL, 'calculate earnings yield / compare earnings yield / earnings yield spread', '[{"en":"The earnings yield of the stock is higher than the risk-free rate.","zh-TW":"該股票的盈利收益率高於無風險利率。"},{"en":"Some investors use earnings yield to compare stocks with bonds.","zh-TW":"部分投資者使用盈利收益率來比較股票和債券。"}]', NULL, NULL, 5, 2267, NULL),
