(2277, 'eco-friendly', '/ˈiːkəʊ ˈfrɛndli/', 'adjective', '{"zh-TW":["環保的；對環境友善的"],"en":["not harmful to the environment"]}', NULL, 'eco-friendly product / eco-friendly packaging', '[{"en":"The company switched to eco-friendly packaging.","zh-TW":"公司改用環保包裝。"},{"en":"Consumers are choosing eco-friendly products more often.","zh-TW":"消費者越來越多地選擇環保產品。"}]', NULL, NULL, 4, 2277, NULL),
(2278, 'eco-tourism', '/''iːkəʊˌtʊərɪzəm/', 'noun', '{"zh-TW":["生態旅遊"],"en":["responsible travel to natural areas that conserves the environment and improves local well-being"]}', NULL, 'promote eco-tourism / eco-tourism destination / sustainable eco-tourism', '[{"en":"Eco-tourism offers travelers a way to enjoy nature without damaging it.","zh-TW":"生態旅遊為旅行者提供了一種享受自然而不破壞它的方式。"},{"en":"The village built eco-tourism facilities to generate income while protecting the forest.","zh-TW":"這個村莊建立了生態旅遊設施，在保護森林的同時創造收入。"}]', '{"adjective":"eco-friendly"}', NULL, 4, 2278, NULL),
(2279, 'ecological corridor', '/ˌiːkəˈlɒdʒɪkəl kəˈrɪdər/', 'noun', '{"zh-TW":["生態廊道"],"en":["a strip of habitat connecting isolated wildlife populations"]}', NULL, 'create ecological corridors / ecological corridor project / wildlife ecological corridor', '[{"en":"Ecological corridors allow animals to move safely between habitat patches.","zh-TW":"生態廊道允許動物在棲息地斑塊之間安全移動。"},{"en":"Establishing ecological corridors reduces the risk of species extinction.","zh-TW":"建立生態廊道降低了物種滅絕的風險。"}]', NULL, NULL, 5, 2279, NULL),
