(2290, 'economies of scale', '/ɪˈkɒnəmiz əv skeɪl/', 'noun', '{"zh-TW":["規模經濟"],"en":["cost advantages gained through increased production or operational size"]}', NULL, 'achieve economies of scale / benefits of economies of scale', '[{"en":"Larger production volumes enabled the company to achieve economies of scale.","zh-TW":"較大的生產量使公司實現了規模經濟。"},{"en":"Economies of scale allow bigger companies to undercut smaller rivals on price.","zh-TW":"規模經濟讓大公司能夠在價格上超越小競爭對手。"}]', NULL, NULL, 5, 2290, NULL),
(2291, 'economies of scope', '/ɪˈkɒnəmiz əv skoʊp/', 'noun', '{"zh-TW":["範疇經濟"],"en":["cost savings from producing multiple different products together"]}', NULL, 'benefit from economies of scope / achieve economies of scope', '[{"en":"The conglomerate achieves economies of scope by sharing distribution networks.","zh-TW":"企業集團通過共享分銷網路實現了範疇經濟。"},{"en":"Economies of scope make diversified companies more cost-efficient.","zh-TW":"範疇經濟使多元化公司更具成本效益。"}]', NULL, NULL, 5, 2291, NULL),
(2292, 'economy', '/ɪˈkɑːnəmi/', 'noun', '{"zh-TW":["經濟；節約"],"en":["the system of trade and industry; careful use of resources"]}', NULL, 'global/national economy', '[{"en":"The economy is expected to grow by 3%.","zh-TW":"預計經濟將增長3%。"},{"en":"We need to practice economy in spending.","zh-TW":"我們需要節約開支。"}]', '{"noun":"economy/economics/economist","adjective":"economic/economical"}', NULL, 3, 2292, NULL),
