(2295, 'ecosystem services', '/ˈiːkəʊˌsɪstəm ˈsɜːrvɪsɪz/', 'noun', '{"zh-TW":["生態系統服務"],"en":["benefits that humans receive from healthy natural ecosystems"]}', NULL, 'value ecosystem services / ecosystem services assessment / lost ecosystem services', '[{"en":"Deforestation destroys ecosystem services such as clean water filtration and carbon storage.","zh-TW":"森林砍伐破壞了清潔水過濾和碳儲存等生態系統服務。"},{"en":"Economists are developing methods to assign monetary value to ecosystem services.","zh-TW":"經濟學家正在開發方法，為生態系統服務賦予貨幣價值。"}]', NULL, NULL, 5, 2295, NULL),
