(2297, 'edge computing', '/edʒ kəmˈpjuːtɪŋ/', 'noun', '{"zh-TW":["邊緣計算"],"en":["processing data near the source rather than in a centralized cloud"]}', NULL, 'implement edge computing / edge computing architecture / edge computing device', '[{"en":"Edge computing reduces latency by processing data closer to the user.","zh-TW":"邊緣計算通過更靠近用戶處理數據來減少延遲。"},{"en":"Autonomous vehicles rely on edge computing for real-time decision-making.","zh-TW":"自動駕駛汽車依賴邊緣計算進行即時決策。"}]', NULL, NULL, 5, 2297, NULL),
(2298, 'edit', '/ˈedɪt/', 'verb', '{"zh-TW":["編輯；修改"],"en":["to prepare written material for publication"]}', NULL, 'edit a document/video', '[{"en":"Please edit the report before submission.","zh-TW":"請在提交前編輯報告。"},{"en":"The article was heavily edited.","zh-TW":"這篇文章經過大量修改。"}]', '{"noun":"edition/editor","verb":"edit","adjective":"editorial"}', NULL, 1, 2298, NULL),
